  const p1 = spawnSync('ffmpeg', ['-hide_banner', '-nostats', '-i', src, '-af', 'loudnorm=I=-23:TP=-3:LRA=20:print_format=json', '-f', 'null', '-'], { encoding: 'utf8' }).stderr || '';
  const m1 = JSON.parse(p1.slice(p1.lastIndexOf('{'), p1.lastIndexOf('}') + 1));
  const ln = `loudnorm=I=-23:TP=-3:LRA=20:measured_I=${m1.input_i}:measured_TP=${m1.input_tp}:measured_LRA=${m1.input_lra}:measured_thresh=${m1.input_thresh}:offset=${m1.target_offset}:linear=true:print_format=json`;
  const p2 = spawnSync('ffmpeg', ['-hide_banner', '-nostats', '-y', '-i', src, '-af', ln, '-ar', '44100', '-c:a', 'libmp3lame', '-b:a', '192k', dst], { encoding: 'utf8' }).stderr || '';
  const m2 = JSON.parse(p2.slice(p2.lastIndexOf('{'), p2.lastIndexOf('}') + 1));""")
s=s.replace("measured: { ...m, method: 'ffmpeg ebur128 (software meter)' }","measured: { ...m, method: 'ffmpeg ebur128 (software meter)' }, normalisation: { method: 'ffmpeg loudnorm two-pass', mode: m2.normalization_type, inputLufs: Number(m1.input_i), inputTruePeak: Number(m1.input_tp) }")
open(p,'w').write(s)
EOF
